function summaryRanges(nums: number[]): string[] {
  const result: string[] = [];
  // Индекс начала текущего диапазона
  let start = 0;

  for (let i = 0; i < nums.length; i++) {
    // Диапазон заканчивается на i, если это последний элемент
    // или следующий элемент идёт не подряд
    const isEnd = i === nums.length - 1 || nums[i + 1] !== nums[i] + 1;
    if (!isEnd) continue;

    // Один элемент — "a", несколько — "a->b"
    result.push(start === i ? `${nums[i]}` : `${nums[start]}->${nums[i]}`);

    // Следующий диапазон начинается сразу после разрыва
    start = i + 1;
  }

  return result;
}

// Время: O(n) — один проход
// Память: O(1) без учёта ответа
